results = {}

# LAMBADA (from decoupling_data.csv)
import csv
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_2/projects/entrainment_gated_ft/artifacts/_project/data/decoupling_data.csv') as f:
    reader = csv.DictReader(f)
    lambada_j = {}
    for row in reader:
        ratio = float(row['attention_ratio'])
        if ratio > 0:
            jh = float(row['jaccard_helped'])
            ju = float(row['jaccard_hurt'])
            lambada_j[ratio] = (jh, ju)
print('LAMBADA:', lambada_j)

# HellaSwag
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_2/projects/entrainment_gated_ft/artifacts/_project/data/hellaswag_jaccard_analysis.json') as f:
    d = json.load(f)
ja = d['jaccard_analysis']
ratio_map = {'h24-1': 0.04, 'h12-1': 0.0769, 'h6-1': 0.1429, 'h3-1': 0.25}
for ratio_name, ratio_val in ratio_map.items():
    if ratio_name in ja:
        pairs = ja[ratio_name]
        j_h, j_u = [], []
        for pair_key, data in pairs.items():
            if '_helped' in pair_key:
                j_h.append(data['J_obs'])
            elif '_hurt' in pair_key:
                j_u.append(data['J_obs'])
        if j_h and j_u:
            print(f'HellaSwag {ratio_name} ({ratio_val}): J_h={sum(j_h)/len(j_h):.4f}, J_u={sum(j_u)/len(j_u):.4f}')

